/**
 * The entry pass (C-11 / O-01, V2-D14; V2-013, DEC-500): a QR that changes every 30 seconds, signed with a secret of
 * the account, generated by the app **without a network** once the secret is cached on the device, and verified by
 * the server at intake (`POST /v1/tickets/intake-pass`). The same pure code runs in the app and on the server, so
 * both always agree on the format (docs/v2/05 §1.3).
 *
 * Token (ASCII, ≈ 72 characters, fits a version 4 QR at level M):
 *
 *     P1.<account>.<vehicle>.<step>.<mac>
 *
 * - `account` — the account id (`customer_accounts.id`), the 16 bytes of the uuid in base64url (22 characters);
 * - `vehicle` — the chosen vehicle (`customer_vehicles.id`) in the same encoding, or `-` when none is chosen;
 * - `step` — `floor(unix seconds / 30)` in decimal, from the device clock corrected by the server time of the last
 *   `GET /v1/customer/pass` (`server_time`);
 * - `mac` — HMAC-SHA256(secret, `point-pass:v1:<account uuid>:<vehicle uuid or ->:<step>`) truncated to its first
 *   10 bytes (80 bits), base64url (14 characters).
 *
 * The secret is 32 random bytes per account (base64url, 43 characters), stored encrypted on the server
 * (`customer_passes.secret_ciphertext`) and delivered only to the signed-in device. The server accepts the current
 * step ± 1 (a 30 s step either side for clock skew and the time to scan), refuses an older or newer step as expired,
 * and refuses a step at or before the last one used for an intake (a screenshot replayed inside the window).
 */
import { hmac } from '@noble/hashes/hmac.js';
import { sha256 } from '@noble/hashes/sha2.js';

/** Seconds of one pass step (V2-D14: «كل 30 ثانية»). */
export const PASS_STEP_S = 30;
/** Steps accepted either side of the server's current step. */
export const PASS_WINDOW_STEPS = 1;
/** Version prefix of the token. */
export const PASS_TOKEN_PREFIX = 'P1';
/** Bytes of the per-account secret. */
export const PASS_SECRET_BYTES = 32;
/** Bytes of the truncated MAC. */
export const PASS_MAC_BYTES = 10;
/** No vehicle chosen (an account without vehicles). */
export const PASS_NO_VEHICLE = '-';
/** The longest token a scanner may hand over (the body limit of `pass_token`). */
export const PASS_TOKEN_MAX_LENGTH = 128;

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
const B64_INDEX = new Map([...B64].map((c, i) => [c, i]));
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** base64url without padding (RFC 4648 §5). */
export function base64UrlEncode(bytes: Uint8Array): string {
  let out = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i]! << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0);
    const left = bytes.length - i;
    out += B64[(n >> 18) & 63]! + B64[(n >> 12) & 63]!;
    if (left > 1) out += B64[(n >> 6) & 63]!;
    if (left > 2) out += B64[n & 63]!;
  }
  return out;
}

/** The bytes of a base64url string without padding, or `null` when it is not one. */
export function base64UrlDecode(text: string): Uint8Array | null {
  if (text.length % 4 === 1) return null;
  const out: number[] = [];
  let acc = 0;
  let bits = 0;
  for (const c of text) {
    const v = B64_INDEX.get(c);
    if (v === undefined) return null;
    acc = (acc << 6) | v;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      out.push((acc >> bits) & 0xff);
    }
  }
  // the unused low bits must be zero, so one byte sequence has exactly one encoding
  if (bits > 0 && (acc & ((1 << bits) - 1)) !== 0) return null;
  return Uint8Array.from(out);
}

function uuidToB64(id: string): string {
  const hex = id.replace(/-/g, '').toLowerCase();
  const bytes = new Uint8Array(16);
  for (let i = 0; i < 16; i++) bytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  return base64UrlEncode(bytes);
}

function b64ToUuid(text: string): string | null {
  if (text.length !== 22) return null;
  const bytes = base64UrlDecode(text);
  if (!bytes || bytes.length !== 16) return null;
  const hex = [...bytes].map((b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** The pass step of an instant (milliseconds since the epoch). */
export function passStep(nowMs: number): number {
  return Math.floor(nowMs / 1000 / PASS_STEP_S);
}

/** Milliseconds until the next step starts (the app re-renders the QR then). */
export function msUntilNextPassStep(nowMs: number): number {
  const stepMs = PASS_STEP_S * 1000;
  return stepMs - (((nowMs % stepMs) + stepMs) % stepMs);
}

function utf8(text: string): Uint8Array {
  return new TextEncoder().encode(text);
}

function secretBytes(secret: string | Uint8Array): Uint8Array {
  if (typeof secret !== 'string') return secret;
  const b = base64UrlDecode(secret);
  if (!b || b.length !== PASS_SECRET_BYTES) throw new Error('pass secret: 32 bytes in base64url expected');
  return b;
}

function passMac(secret: Uint8Array, accountId: string, vehicleId: string | null, step: number): string {
  const msg = `point-pass:v1:${accountId.toLowerCase()}:${vehicleId?.toLowerCase() ?? PASS_NO_VEHICLE}:${step}`;
  return base64UrlEncode(hmac(sha256, secret, utf8(msg)).subarray(0, PASS_MAC_BYTES));
}

function constantTimeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

export interface PassTokenInput {
  /** The account secret: base64url as delivered by `GET /v1/customer/pass`, or its bytes. */
  secret: string | Uint8Array;
  accountId: string;
  /** The vehicle chosen on C-11, `null` without one. */
  vehicleId: string | null;
  /** The (server-corrected) time in milliseconds; the step is derived from it unless `step` is given. */
  nowMs?: number;
  step?: number;
}

/** The token shown as QR on C-11 for one step. */
export function generatePassToken(input: PassTokenInput): string {
  if (!UUID_RE.test(input.accountId)) throw new Error('pass: account id must be a uuid');
  if (input.vehicleId !== null && !UUID_RE.test(input.vehicleId))
    throw new Error('pass: vehicle id must be a uuid');
  const step = input.step ?? passStep(input.nowMs ?? Date.now());
  if (!Number.isSafeInteger(step) || step < 0) throw new Error('pass: step must be a non-negative integer');
  const mac = passMac(secretBytes(input.secret), input.accountId, input.vehicleId, step);
  const vehicle = input.vehicleId === null ? PASS_NO_VEHICLE : uuidToB64(input.vehicleId);
  return [PASS_TOKEN_PREFIX, uuidToB64(input.accountId), vehicle, String(step), mac].join('.');
}

export interface ParsedPassToken {
  accountId: string;
  vehicleId: string | null;
  step: number;
  mac: string;
}

/** The fields of a well-formed token (no signature check), or `null`. */
export function parsePassToken(token: string): ParsedPassToken | null {
  if (typeof token !== 'string' || token.length > PASS_TOKEN_MAX_LENGTH) return null;
  const parts = token.trim().split('.');
  if (parts.length !== 5 || parts[0] !== PASS_TOKEN_PREFIX) return null;
  const [, acct, veh, stepText, mac] = parts as [string, string, string, string, string];
  const accountId = b64ToUuid(acct);
  const vehicleId = veh === PASS_NO_VEHICLE ? null : b64ToUuid(veh);
  if (!accountId || (veh !== PASS_NO_VEHICLE && !vehicleId)) return null;
  if (!/^(0|[1-9][0-9]{0,14})$/.test(stepText)) return null;
  const decodedMac = base64UrlDecode(mac);
  if (!decodedMac || decodedMac.length !== PASS_MAC_BYTES) return null;
  return { accountId, vehicleId, step: Number(stepText), mac };
}

export type PassVerification =
  | { ok: true; accountId: string; vehicleId: string | null; step: number; secretIndex: number }
  /** `malformed`: not a pass token; `bad_mac`: not signed by any of the secrets; `stale`/`future`: outside the window. */
  | { ok: false; reason: 'malformed' | 'bad_mac' | 'stale' | 'future'; step?: number };

/**
 * Verifies a token against the account's secrets (the current one first, then a previous one still valid after a
 * rotation) and the server time: the signature first, then the step within ± `window` (default 1).
 */
export function verifyPassToken(input: {
  token: string;
  secrets: readonly (string | Uint8Array)[];
  nowMs: number;
  window?: number;
}): PassVerification {
  const p = parsePassToken(input.token);
  if (!p) return { ok: false, reason: 'malformed' };
  const index = input.secrets.findIndex((s) =>
    constantTimeEqual(passMac(secretBytes(s), p.accountId, p.vehicleId, p.step), p.mac),
  );
  if (index < 0) return { ok: false, reason: 'bad_mac' };
  const current = passStep(input.nowMs);
  const window = input.window ?? PASS_WINDOW_STEPS;
  if (p.step < current - window) return { ok: false, reason: 'stale', step: p.step };
  if (p.step > current + window) return { ok: false, reason: 'future', step: p.step };
  return { ok: true, accountId: p.accountId, vehicleId: p.vehicleId, step: p.step, secretIndex: index };
}
